RECOVERY_SOURCE = ''
HELD_OUT_SOURCE = ''

from pathlib import Path
import base64,collections,datetime,hashlib,json,types
import pyarrow as pa
import pyarrow.parquet as pq
base=Path.home()/'code/Behavior-1k Challenge'
repo=base/'BEHAVIOR-VLAs'
labels=repo/'eval_results/subtask_improvement_goal/original_training_inputs/subtask_segments.v1.parquet'
meta=repo/'eval_results/subtask_improvement_goal/original_dataset_metadata'
output=base/'analysis/retraining_20261013/leading_fill_v1'
expected='870086137b5fac4ff8a701e6e539cdc99ee43d3efacb81028a2ae0b4f78fff2d'
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
assert sha(labels)==expected,'Original annotation identity differs'
assert not output.exists(),'Refusing to overwrite existing results'
recovery=types.ModuleType('frozen_recovery_index')
module_bytes=base64.b64decode(RECOVERY_SOURCE)
exec(compile(module_bytes,'frozen_recovery_index.py','exec'),recovery.__dict__)
held=json.loads(base64.b64decode(HELD_OUT_SOURCE)); heldset=set(map(tuple,held))
rows=pq.read_table(labels).to_pylist()
groups=collections.defaultdict(list)
for i,row in enumerate(rows):groups[row['episode_index']].append((i,row))
metadata={}
tasks={r['task_index']:r['task_name'] for r in map(json.loads,(meta/'meta/tasks.jsonl').read_text().splitlines())}
for p in sorted((meta/'meta/episodes').glob('chunk-*/*.parquet')):
 for row in pq.read_table(p).to_pylist():
  assert row['episode_index'] not in metadata
  metadata[row['episode_index']]={'length':row['length'],'task_name':tasks[row['task_index']],'task_instance_id':row['task_instance_id']}
assert len(metadata)==20000 and set(metadata)==set(groups)
fill_rows=[]; dropped=[]; lengths=[]
for ep,items in sorted(groups.items()):
 items.sort(key=lambda pair:pair[1]['start'])
 cursor=0
 for _,r in items:
  assert type(r['start']) is int and r['start']==cursor and r['end']>r['start']
  cursor=r['end']
 assert cursor==metadata[ep]['length']
 first=next((i for i,(_,r) in enumerate(items) if r['subtask'] and r['subtask'].strip()),None)
 assert first is not None,'Entirely unlabelled episode'
 assert all(r['subtask'] and r['subtask'].strip() for _,r in items[first:]),'Nonleading empty interval'
 if first:
  dropped.append(ep); end=items[first][1]['start']; lengths.append(end)
  label=items[first][1]['subtask'].strip()
  assert label==items[first][1]['subtask'],'Noncanonical source label'
  fill_rows.extend((index,label,items[first][1]['start'],items[first][1]['end']) for index,_ in items[:first])
assert len(dropped)==3949 and sum(lengths)==291015
recovered=recovery.prepare_index(meta,labels,dropped,repo_id='behavior-1k/2026-challenge-demos',root_id='expert_original',source_kind='recovered',held_out_instances=held,fill_leading_with_first_subtask=True)
replay=recovery.prepare_index(meta,labels,sorted(set(metadata)-set(dropped)),repo_id='behavior-1k/2026-challenge-demos',root_id='expert_original',source_kind='replay',held_out_instances=held)
for index in (recovered,replay):recovery.verify_source_files(index)
output.mkdir(parents=True)
def save(name,value):
 with (output/name).open('x') as stream:json.dump(value,stream,indent=2,ensure_ascii=False,allow_nan=False);stream.write('\n')
(output/'frozen_recovery_index.py').write_bytes(module_bytes)
(output/'held_out_task_instances.json').write_bytes(base64.b64decode(HELD_OUT_SOURCE))
(output/'dropped_episode_indices.txt').write_text(''.join(str(ep)+'\n' for ep in dropped))
save('recovered_index.json',recovered);save('replay_index.json',replay)
# Full derived label table retains original rows, boundaries and all columns.
# The executable training indexes above merge each filled prefix with its first
# labelled segment, and explicitly retain the original annotation boundary.
derived=[]
for row in rows:
 r=dict(row);r['original_subtask']=r['subtask']
 r['imputation_source_start']=None;r['imputation_source_end']=None
 derived.append(r)
for i,label,start,end in fill_rows:
 derived[i]['subtask']=label
 if 'annotated' in derived[i]:derived[i]['annotated']=False
 if 'is_annotated' in derived[i]:derived[i]['is_annotated']=False
 derived[i]['label_fill_provenance']='imputed_leading'
 derived[i]['imputation_source_start']=start;derived[i]['imputation_source_end']=end
for i,r in enumerate(derived):
 r.setdefault('label_fill_provenance','original')
 original=rows[i]
 assert all(r[k]==v for k,v in original.items() if k not in ('subtask','annotated','is_annotated'))
 if r['label_fill_provenance']=='original':assert r['subtask']==original['subtask']
pq.write_table(pa.Table.from_pylist(derived),output/'subtask_segments.leading_fill_v1.parquet')
readback=pq.read_table(output/'subtask_segments.leading_fill_v1.parquet').to_pylist()
assert len(readback)==len(rows) and all(r['subtask'] and r['subtask'].strip() for r in readback)
assert sum(r['end']-r['start'] for r in readback if r['label_fill_provenance']=='imputed_leading')==291015
assert sha(labels)==expected,'Source modified unexpectedly'
summary={'kind':'original_expert_leading_fill_applied','completed_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'host':'macpro','output_directory':str(output),'source_labels':str(labels),'source_labels_sha256':expected,'metadata_root':str(meta),'original_labels_unchanged':True,'video_or_actions_modified':False,'training_launched':False,'original_total_episodes':len(metadata),'filled_episodes':len(dropped),'filled_frames':sum(lengths),'filled_segment_rows':len(fill_rows),'length_histogram':dict(sorted(collections.Counter(lengths).items())),'one_frame_prefix_episodes':sum(x==1 for x in lengths),'prefix_frames_min':min(lengths),'prefix_frames_max':max(lengths),'prefix_frames_mean':sum(lengths)/len(lengths),'held_out_task_instance_pairs':len(held),'recovered_training':recovered['provenance']['statistics'],'replay_training':replay['provenance']['statistics'],'training_episode_count':len(recovered['episodes'])+len(replay['episodes']),'index_label_policy':'first_nonempty_subtask; imputed provenance preserved; first span merged only in training index','training_host_ready':False,'training_host_requirements':['restore original expert data/videos at mapped root','verify source file hashes','real training-reader video/action alignment','GPU training and checkpoint restore checks'],'files':{p.name:{'bytes':p.stat().st_size,'sha256':sha(p)} for p in output.iterdir() if p.is_file()}}
save('application_receipt.json',summary)
print(json.dumps({k:v for k,v in summary.items() if k not in ('files','length_histogram')},ensure_ascii=False),flush=True)
